    // ══════════════════════════════════════════════════════════════
    // RIGHTS
    //
    // The register the nine-page removal took out. It is rebuilt because the
    // route, film_rights and the MCP tools were never removed with it, so every
    // one of its thirteen fields was reachable by curl and by nothing else --
    // and its orphaned handler was left calling a loadRightsPage() that has not
    // existed since.
    //
    // Recorded, never enforced. Nothing here blocks a generation or an export:
    // a gate on rights would be switched off the first time it stopped a
    // director mid-shot, and then the record would go with it.
    // ══════════════════════════════════════════════════════════════
    let RIGHTS_VOCAB = null;

    async function loadRights() {
        if (!state.currentProject) return;
        const host = document.getElementById('rightsList');
        let data;
        try { data = await api(`/projects/${state.currentProject.id}/rights`); }
        catch (err) { host.innerHTML = `<p class="text-sm text-muted">Could not read the register: ${esc(err.message)}</p>`; return; }
        RIGHTS_VOCAB = data.vocabulary || null;
        state.rightsRows = data.rights || [];

        const filter = document.getElementById('rightsFilter');
        if (RIGHTS_VOCAB && filter.options.length <= 1) {
            filter.innerHTML = '<option value="">All statuses</option>'
                + RIGHTS_VOCAB.status.map(v => `<option value="${esc(v)}">${esc(v)}</option>`).join('');
        }
        const want = filter.value;
        const rows = want ? state.rightsRows.filter(r => r.status === want) : state.rightsRows;

        const counts = data.by_status || {};
        document.getElementById('rightsSummary').innerHTML = Object.keys(counts).length
            ? `<div class="tag-row">${Object.entries(counts).map(([k, n]) =>
                `<span class="tag"${k === 'cleared' ? ' style="border-color:var(--gl-success);color:var(--gl-success);"' : ''}>`
                + `${esc(k)}: ${n}</span>`).join('')}</div>`
            : '';

        if (!rows.length) {
            host.innerHTML = '<p class="text-sm text-muted">Nothing recorded'
                + (want ? ' with that status.' : ' yet.') + '</p>';
            return;
        }
        host.innerHTML = rows.map(r => {
            const good = r.status === 'cleared';
            const bad = r.status === 'expired' || r.status === 'blocked';
            const colour = good ? 'var(--gl-success)' : bad ? 'var(--gl-danger,#ef4444)' : 'var(--gl-warning,#f59e0b)';
            return `<div class="card" style="margin-bottom:6px;">
                <div class="flex-between" style="gap:8px;flex-wrap:wrap;min-width:0;">
                    <div style="min-width:0;">
                        <strong>${esc(r.subject || '')}</strong>
                        <div class="text-sm text-muted">${esc((r.rights_type || '').replace(/_/g, ' '))}
                            ${r.owner ? '&middot; ' + esc(r.owner) : ''}
                            ${r.territory ? '&middot; ' + esc(r.territory) : ''}
                            ${r.expires_on ? '&middot; until ' + esc(String(r.expires_on).slice(0, 10)) : ''}</div>
                        <div class="tag-row" style="margin-top:4px;">
                            <span class="tag" style="border-color:${colour};color:${colour};">${esc(r.status || 'unknown')}</span>
                            <span class="tag">${esc(r.entity_type || 'asset')}</span>
                            ${r.restrictions ? '<span class="tag">restricted</span>' : ''}
                        </div>
                    </div>
                    <div class="card-actions">
                        <button class="btn btn-secondary btn-sm" onclick="openRight('${r.id}')">Edit</button>
                        <button class="btn btn-secondary btn-sm" onclick="deleteRight('${r.id}')">Delete</button>
                    </div>
                </div>
            </div>`;
        }).join('');
    }

    function openRight(id) {
        if (!RIGHTS_VOCAB) return setStatus('This server serves no rights vocabulary — it may predate it.');
        const r = id ? (state.rightsRows || []).find(x => x.id === id) || {} : {};
        showModalHtml('rightModal', `
            <div class="modal-header">
                <h3>${id ? 'Edit record' : 'New rights record'}</h3>
                <button class="modal-close" onclick="closeModal('rightModal')">&times;</button>
            </div>
            <div class="modal-body">
                <div class="form-group"><label>Subject</label>
                    <input type="text" id="rightSubject" data-field="subject" maxlength="500" value="${esc(r.subject || '')}"
                           placeholder="What this record is about — a person, a track, a model">
                    <span class="text-sm text-muted">Required.</span></div>
                <div class="form-group"><label>Type</label>
                    <select id="rightType" data-field="rights_type">${vocabOptions(RIGHTS_VOCAB.rights_type, r.rights_type || 'commercial_use')}</select></div>
                <div class="form-group"><label>Status</label>
                    <select id="rightStatus" data-field="status">${vocabOptions(RIGHTS_VOCAB.status, r.status || 'unknown')}</select></div>
                ${r.origin === 'derived' ? `<div class="form-group"><label>Origin</label><span class="text-sm text-muted">Derived — this file's rights are computed from what it was made from, so they follow the sources rather than being declared here.</span></div>` : `<div class="form-group"><label>Origin</label>
                    <select id="rightOrigin" data-field="origin">${vocabOptions(RIGHTS_VOCAB.origin || ['original', 'generated', 'licensed', 'public_domain', 'unknown'], r.origin || 'unknown')}</select>
                    <span class="text-sm text-muted">What the material is: your own, generated by a provider, licensed, public domain, or not known. Nothing is assumed.</span></div>`}
                <div class="form-group"><label>What it attaches to</label>
                    <select id="rightEntityType" data-field="entity_type">${vocabOptions(RIGHTS_VOCAB.entity_type, r.entity_type || 'asset')}</select></div>
                <div class="form-group"><label>Its id</label>
                    <input type="text" id="rightEntityId" data-field="entity_id" maxlength="100" value="${esc(r.entity_id || '')}"
                           placeholder="Optional — the character, asset or cue this is about"></div>
                <div class="form-group"><label>Owner</label>
                    <input type="text" id="rightOwner" data-field="owner" maxlength="500" value="${esc(r.owner || '')}"
                           placeholder="Who holds the right"></div>
                <div class="form-group"><label>Source</label>
                    <input type="text" id="rightSource" data-field="source" maxlength="500" value="${esc(r.source || '')}"
                           placeholder="Where it came from"></div>
                <div class="form-group"><label>Licence URL</label>
                    <input type="text" id="rightUrl" data-field="license_url" maxlength="1000" value="${esc(r.license_url || '')}"
                           placeholder="https://…"></div>
                <div class="form-group"><label>Consent reference</label>
                    <input type="text" id="rightConsent" data-field="consent_reference" maxlength="500"
                           value="${esc(r.consent_reference || '')}"
                           placeholder="The signed release, by its own reference">
                    <span class="text-sm text-muted">For a likeness or a voice: what you would produce if asked.</span></div>
                <div class="form-group"><label>Territory</label>
                    <input type="text" id="rightTerritory" data-field="territory" maxlength="200" value="${esc(r.territory || '')}"
                           placeholder="e.g. worldwide, or UK &amp; Ireland"></div>
                <div class="form-group"><label>Expires</label>
                    <input type="date" id="rightExpires" data-field="expires_on"
                           value="${esc(String(r.expires_on || '').slice(0, 10))}">
                    <span class="text-sm text-muted">Blank means it does not expire.</span></div>
                <div class="form-group"><label>Restrictions</label>
                    <textarea id="rightRestrictions" data-field="restrictions" rows="2" maxlength="2000">${esc(r.restrictions || '')}</textarea>
                    <span class="text-sm text-muted">What you may NOT do with it. Read by a person, not by the engine.</span></div>
                <div class="form-group"><label>Notes</label>
                    <textarea id="rightNotes" data-field="notes" rows="2" maxlength="2000">${esc(r.notes || '')}</textarea></div>
            </div>
            <div class="modal-footer">
                <button class="btn btn-secondary" onclick="closeModal('rightModal')">Cancel</button>
                <button class="btn btn-primary" onclick="saveRight(${id ? `'${id}'` : 'null'})">Save</button>
            </div>`);
    }

    async function saveRight(id) {
        const v = i => (document.getElementById(i) || {}).value;
        const body = {
            subject: v('rightSubject'), rights_type: v('rightType'), status: v('rightStatus'), origin: v('rightOrigin'),
            entity_type: v('rightEntityType'), entity_id: v('rightEntityId'),
            owner: v('rightOwner'), source: v('rightSource'), license_url: v('rightUrl'),
            consent_reference: v('rightConsent'), territory: v('rightTerritory'),
            expires_on: v('rightExpires'), restrictions: v('rightRestrictions'), notes: v('rightNotes'),
        };
        if (!body.subject.trim()) return setStatus('A rights record needs a subject');
        try {
            await api(id ? `/rights/${id}` : `/projects/${state.currentProject.id}/rights`,
                { method: id ? 'PUT' : 'POST', body: JSON.stringify(body) });
            closeModal('rightModal');
            setStatus(id ? 'Record updated' : 'Record added');
            loadRights();
        } catch (err) { setStatus('Error: ' + err.message); }
    }

    async function deleteRight(id) {
        if (!confirm('Remove this rights record?\n\nThe clearance it documents is not affected — this '
            + 'only removes the note that you had it.')) return;
        try { await api(`/rights/${id}`, { method: 'DELETE' }); loadRights(); setStatus('Record removed'); }
        catch (err) { setStatus('Error: ' + err.message); }
    }
